-- Owner-authorized menu photo transcription. Prices corrected for future orders only.
-- Existing order item snapshots and retired menu rows remain intact.
begin;
select pg_advisory_xact_lock(814208);
-- The trial-only braised-pork dish is absent from the supplied real menu; keep its history.
update public.menu_items set is_active=false where code='braised-pork-noodles';
update public.menu_categories set is_active=false where code='yentafo' and not exists(select 1 from public.menu_items where category_id=public.menu_categories.id and is_active);
commit;
